function period(s){return date(last(s)?.date,s?.frequency)}
function source(s){return s?`${esc(s.provider)} · ${esc(s.sourceCode)}`:'Fuente pendiente'}
function shortUnit(s){const u=s?.unit||'';if(u==='USD/barril')return'US$/bbl';if(u==='p.p.')return'pp';if(/%|porcent/i.test(u))return'%';if(/millones.*USD|millones de US\$/i.test(u))return'US$ MM';if(/centavos/i.test(u))return'¢/lb';if(/S\/.*USD|soles.*d.lar/i.test(u))return'S/';return u.length>14?'':u}
function pageHead(title){return`<div class="page-head"><h1>${title}</h1></div>`}
