$('#content').addEventListener('click',e=>{const t=e.target.closest('button,[data-detail]');if(!t)return;if(t.dataset.agendaOpen){view='agenda';location.hash=view;agenda.setScope?.('all');render();window.scrollTo({top:0,behavior:'smooth'});return}if(t.dataset.peruTopic){if(peruTopic!==t.dataset.peruTopic){peruTopic=t.dataset.peruTopic;render()}return}if(t.dataset.worldTopic){if(worldTopic!==t.dataset.worldTopic){worldTopic=t.dataset.worldTopic;render()}return}if(t.dataset.preset){applyPreset(t.dataset.preset);return}if(t.dataset.chartInfo)return chartInfo(t.dataset.chartInfo);if(t.dataset.detail)return detail(t.dataset.detail,t.dataset.derived||'');if(t.dataset.table)return showData(t.dataset.table);if(t.dataset.png)return png(t.dataset.png);if(t.dataset.expand)return expand(t.dataset.expand);if(t.dataset.country){if(countries.includes(t.dataset.country)){if(countries.length===1)return toast('Mantén al menos un país.');countries=countries.filter(c=>c!==t.dataset.country)}else countries.push(t.dataset.country);year='';render();return}if(t.id==='common-year'){year=commonDates(countries.map(c=>wb(c,metric)).filter(Boolean)).at(-1)||'';if(!year)return toast('No existe un año con datos para todos los países seleccionados.');render();return}if(t.id==='catalog-more'){catalogLimit+=100;const top=$('#catalog-list').scrollTop;renderCatalog();$('#catalog-list').scrollTop=top;return}if(t.dataset.select){const id=t.dataset.select;if(selected.includes(id))selected=selected.filter(s=>s!==id);else if(selected.length<4)selected.push(id);else return toast('Puedes comparar hasta cuatro series.');rerenderExplorer();return}if(t.dataset.remove){selected=selected.filter(s=>s!==t.dataset.remove);if(!selected.length)selected=[b('inflation').id];rerenderExplorer();return}if(t.id==='reset-explorer'){selected=[b('inflation').id,b('core').id];mode='level';chartType='line';render()}if(t.id==='retry')refresh(true)});
