$('#content').addEventListener('change',e=>{if(e.target.id==='wb-metric'){metric=e.target.value;year='';render()}if(e.target.id==='wb-year'){year=e.target.value;render()}if(e.target.id==='provider-filter'){catalogProvider=e.target.value;catalogLimit=100;renderCatalog()}if(e.target.id==='country-filter'){catalogCountry=e.target.value;catalogLimit=100;renderCatalog()}if(e.target.id==='category-filter'){catalogCategory=e.target.value;catalogLimit=100;renderCatalog()}if(e.target.id==='transform'){mode=e.target.value;renderExploreChart()}if(e.target.id==='chart-type'){chartType=e.target.value;renderExploreChart()}});
