$('#close-dialog').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>{document.body.style.overflow='';document.documentElement.classList.remove('chart-export-open');window.dispatchEvent(new Event('sbs:scroll-restored'));for(const id of['detail-chart','expanded-chart']){const c=charts.find(c=>c.__chartId===id);if(c){c.dispose();charts=charts.filter(x=>x!==c)}chartRows.delete(id)}});$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
let resizeFrame;window.addEventListener('resize',()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>charts.forEach(c=>{if(!c.isDisposed?.())c.resize()}))});window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==view&&tabs.some(t=>t[0]===next)){view=next;render()}});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});window.addEventListener('focus',()=>refresh());setInterval(()=>{if(!document.hidden)refresh()},300000);initTreasuryShell(()=>{if(data)render()});refresh(true);

const rangeOptions=['3','5','10','all'];
function updateRange(value){if(value===range)return;range=value;$('#range').value=value;save('range',range);render();syncRangeButtons()}
function syncRangeButtons(){const i=rangeOptions.indexOf(range);$('#range-prev').disabled=i<=0;$('#range-next').disabled=i>=rangeOptions.length-1}
$('#range-prev').onclick=()=>updateRange(rangeOptions[Math.max(0,rangeOptions.indexOf(range)-1)]);
$('#range-next').onclick=()=>updateRange(rangeOptions[Math.min(rangeOptions.length-1,rangeOptions.indexOf(range)+1)]);
$('#range-all').onclick=()=>updateRange('all');$('#range').onchange=e=>updateRange(e.target.value);syncRangeButtons();
